func schema_pkg_apis_application_v1alpha1_BackoffConfig(ref common.ReferenceCallback) common.OpenAPIDefinition {
	return common.OpenAPIDefinition{
		Schema: spec.Schema{
			SchemaProps: spec.SchemaProps{
				Description: "BackoffConfig is exponential backoff used for retries (mirrors Application sync retry backoff naming: duration / factor / maxDuration). Use this shape for any retry/backoff settings group rather than ad-hoc timeout/cap/baseBackoff field names.",
				Type:        []string{"object"},
				Properties: map[string]spec.Schema{
					"duration": {
						SchemaProps: spec.SchemaProps{
							Description: "Duration is the initial / base wait before the first retry. Self-heal: controller.self.heal.backoff.timeout.seconds (default 2s). K8s client: *.k8sclient.retry.base.backoff (default 100ms; doubles each retry up to an internal 10s cap — only Duration is used for k8s client). Application sync: backoff.duration.",
							Ref:         ref("k8s.io/apimachinery/pkg/apis/meta/v1.Duration"),
						},
					},
					"factor": {
						SchemaProps: spec.SchemaProps{
							Description: "Factor multiplies the wait after each failed attempt. Self-heal: controller.self.heal.backoff.factor (default 3). Unused for current k8s client retry (reserved for shape consistency).",
							Type:        []string{"integer"},
							Format:      "int32",
						},
					},
					"maxDuration": {
						SchemaProps: spec.SchemaProps{
							Description: "MaxDuration is the maximum wait between retries. Self-heal: controller.self.heal.backoff.cap.seconds (default 300s). Unused for current k8s client retry (hard-capped at 10s in code).",
							Ref:         ref("k8s.io/apimachinery/pkg/apis/meta/v1.Duration"),
						},
					},
				},
			},
		},
		Dependencies: []string{
			"k8s.io/apimachinery/pkg/apis/meta/v1.Duration"},
	}
}

